/**
 * Python-like exception objects.
 *
 * The original program lets exceptions escape `main()`, so the observable
 * behaviour of a failure is: a traceback on stderr and exit code 1.  To
 * reproduce that faithfully each error carries the name Python would print
 * ("ValueError", "TypeError", ...) plus the library frames that appeared
 * between `main()` and the raise site.
 */

export class PythonError extends Error {
  /**
   * @param {string} pyType   Exception class name as printed by Python.
   * @param {string} pyMessage Text printed after "PyType: ".
   * @param {Array<{file: string, line: number, func: string, source?: string, caret?: string}>} frames
   *        Frames below the calling module, outermost first.
   */
  constructor(pyType, pyMessage, frames = []) {
    super(`${pyType}: ${pyMessage}`);
    this.pyType = pyType;
    this.pyMessage = pyMessage;
    this.frames = frames;
  }
}

export class PyValueError extends PythonError {
  constructor(message, frames = []) {
    super('ValueError', message, frames);
  }
}

export class PyTypeError extends PythonError {
  constructor(message, frames = []) {
    super('TypeError', message, frames);
  }
}

export class PyMemoryError extends PythonError {
  constructor(message = '', frames = []) {
    super('MemoryError', message, frames);
  }
}

