/**
 * Python `repr()` / `print()` formatting helpers.
 *
 * Integers are modelled as BigInt so that arbitrary-precision results
 * (large bit widths produce values well past 2**53) print exactly as
 * CPython prints them.
 */

/** repr() of a Python str. */
export function pyReprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x20 || cp === 0x7f || (cp >= 0x80 && cp <= 0x9f)) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

/** repr() of a Python int. */
export function pyReprInt(value) {
  return value.toString();
}

/** repr() of the list objects `convertbits` returns. */
export function pyReprList(items) {
  return '[' + items.map(pyRepr).join(', ') + ']';
}

/** repr() dispatch for the value kinds this program can print. */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (Array.isArray(value)) return pyReprList(value);
  if (typeof value === 'bigint' || typeof value === 'number') return pyReprInt(value);
  if (typeof value === 'string') return pyReprStr(value);
  return String(value);
}

/** print(value) — str() of a list/None/int equals its repr(). */
export function pyPrint(value) {
  process.stdout.write(pyRepr(value) + '\n');
}

