/**
 * CPython's `int(str)` conversion.
 *
 * Accepts surrounding whitespace, an optional ASCII sign, single underscores
 * between digits and any Unicode decimal digit; anything else raises
 * ValueError with CPython's exact message.
 */

import { PyValueError } from './pyerrors.mjs';
import { pyReprStr } from './pyrepr.mjs';

// Characters str.strip() removes (Python's str.isspace set, ASCII + Unicode).
const WHITESPACE = /[\t\n\v\f\r\x1c-\x1f\x20\x85   -     　]/;

const ND = /\p{Nd}/u;

/** Numeric value of a Unicode decimal digit, or -1 if it is not one. */
function digitValue(ch) {
  const cp = ch.codePointAt(0);
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  if (!ND.test(ch)) return -1;
  // Decimal digit blocks are contiguous runs of ten, so the distance down to
  // the first non-digit code point is the digit's value.
  let value = 0;
  while (value < 9 && ND.test(String.fromCodePoint(cp - value - 1))) value += 1;
  return value;
}

function stripWhitespace(s) {
  let start = 0;
  let end = s.length;
  while (start < end && WHITESPACE.test(s[start])) start += 1;
  while (end > start && WHITESPACE.test(s[end - 1])) end -= 1;
  return s.slice(start, end);
}

/**
 * int(text) with base 10.
 *
 * @param {string} text
 * @returns {bigint}
 */
export function pyInt(text) {
  const invalid = () =>
    new PyValueError(`invalid literal for int() with base 10: ${pyReprStr(text)}`);

  const body = stripWhitespace(text);
  let index = 0;
  let negative = false;
  if (body[index] === '+' || body[index] === '-') {
    negative = body[index] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; index < body.length; index += 1) {
    const ch = body[index];
    if (ch === '_') {
      // Underscores are only legal between two digits.
      if (!previousWasDigit) throw invalid();
      previousWasDigit = false;
      continue;
    }
    const value = digitValue(ch);
    if (value < 0) throw invalid();
    digits += String(value);
    previousWasDigit = true;
  }
  if (!previousWasDigit) throw invalid();

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

