/**
 * Traceback rendering for exceptions that escape `main()`.
 *
 * The frozen executable prints the standard CPython traceback followed by the
 * PyInstaller bootloader's failure line, then exits with status 1.
 */

const SCRIPT_NAME = 'test14.py';
const MODULE_LABEL = 'test14';

/** Frames of the entry module, keyed by the statement that raised. */
export const MAIN_FRAMES = {
  module: {
    file: SCRIPT_NAME,
    line: 19,
    func: '<module>',
    source: '    main()',
  },
  parseData: {
    file: SCRIPT_NAME,
    line: 12,
    func: 'main',
    source: "    data = list(map(int, args.a.split(',')))",
    caret: ' '.repeat(11) + '^'.repeat(33),
  },
  step1: {
    file: SCRIPT_NAME,
    line: 13,
    func: 'main',
    source:
      '    step1 = bech32.convertbits(data, args.b, args.c)  # Convert from bits to intermediate bits',
    caret: ' '.repeat(12) + '^'.repeat(40),
  },
  step2: {
    file: SCRIPT_NAME,
    line: 14,
    func: 'main',
    source:
      '    step2 = bech32.convertbits(step1, args.c, args.d)  # Convert from intermediate to final bits',
    caret: ' '.repeat(12) + '^'.repeat(41),
  },
};

function renderFrame(frame) {
  let text = `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;
  if (frame.source !== undefined) text += frame.source + '\n';
  if (frame.caret !== undefined) text += frame.caret + '\n';
  return text;
}

/**
 * Print a traceback for `error` and terminate with Python's exit status.
 *
 * @param {import('./pyerrors.mjs').PythonError} error
 * @param {Array<object>} callFrames Frames above the error's own frames.
 */
export function reportUnhandled(error, callFrames) {
  const frames = [...callFrames, ...(error.frames || [])];
  let out = 'Traceback (most recent call last):\n';
  for (const frame of frames) out += renderFrame(frame);
  out += error.pyMessage === ''
    ? `${error.pyType}\n`
    : `${error.pyType}: ${error.pyMessage}\n`;
  out += `[PYI-${process.pid}:ERROR] Failed to execute script '${MODULE_LABEL}' due to unhandled exception!\n`;
  process.stderr.write(out);
  process.exitCode = 1;
}

