/**
 * Minimal re-implementation of the pieces of Python's `argparse` this program
 * relies on: long options with required values, `--opt=value` and `--opt value`
 * forms, unique-prefix abbreviation, `-h/--help`, and argparse's exact usage,
 * help and error texts (exit status 2 on a parse error).
 */

import { pyInt } from './pyint.mjs';
import { pyReprStr } from './pyrepr.mjs';

// argparse treats a "-…" token as a value when it looks like a negative number
// and no registered option looks like one.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const TYPE_NAMES = new Map([[pyInt, 'int'], [String, 'string']]);

export const int = pyInt;
export const str = String;

class Action {
  constructor({ optionStrings, dest, metavar, type, required, help, kind }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.metavar = metavar;
    this.type = type;
    this.required = required;
    this.help = help;
    this.kind = kind; // 'store' | 'help'
  }

  /** argparse's `_get_action_name`. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** "--a A" / "-h, --help" as shown in usage and the options list. */
  formatInvocation(forUsage) {
    if (this.kind === 'help') {
      return forUsage ? this.optionStrings[0] : this.optionStrings.join(', ');
    }
    if (forUsage) return `${this.optionStrings[0]} ${this.metavar}`;
    return this.optionStrings.map((o) => `${o} ${this.metavar}`).join(', ');
  }
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog;
    this.actions = [];
