/**
 * `bech32.convertbits` — general power-of-2 base conversion.
 *
 * Reconstructed from the reference package's observable behaviour:
 *   - values are accumulated MSB-first into a sliding window;
 *   - a value that is negative or wider than `frombits` makes the whole call
 *     return None;
 *   - with padding enabled (the default) a trailing partial group is emitted;
 *   - shift widths are computed *before* the input is iterated, so a negative
 *     `tobits` fails even when `data` is None.
 *
 * All arithmetic uses BigInt: bit widths are unbounded in Python, and large
 * widths produce values far beyond IEEE-754 integer precision.
 */

import { PyValueError, PyTypeError, PyMemoryError } from '../pyerrors.mjs';

// Line numbers of the reference implementation, so escaping exceptions carry
// the same frame the original traceback shows.
const LINE_MAXV = 88;
const LINE_MAX_ACC = 89;
const LINE_ITERATE = 90;
const LINE_CHECK_VALUE = 91;
const LINE_ACCUMULATE = 92;

const frame = (line) => [{ file: 'bech32/__init__.py', line, func: 'convertbits' }];

/** Python's `x << count`, which rejects negative shift counts. */
function shiftLeft(x, count, line) {
  if (count < 0n) throw new PyValueError('negative shift count', frame(line));
  try {
    return x << count;
  } catch {
    throw new PyMemoryError('', frame(line));
  }
}

/** Python's `x >> count`, which rejects negative shift counts. */
function shiftRight(x, count, line) {
  if (count < 0n) throw new PyValueError('negative shift count', frame(line));
  return x >> count;
}

/**
 * convertbits(data, frombits, tobits, pad=True)
 *
 * @param {bigint[]|null} data
 * @param {bigint} frombits
 * @param {bigint} tobits
 * @param {boolean} [pad]
 * @returns {bigint[]|null} Regrouped values, or None when the input is invalid.
 */
export function convertbits(data, frombits, tobits, pad = true) {
  let acc = 0n;
  let bits = 0n;
  const ret = [];
  const maxv = shiftLeft(1n, tobits, LINE_MAXV) - 1n;
  const maxAcc = shiftLeft(1n, frombits + tobits - 1n, LINE_MAX_ACC) - 1n;

  if (data === null || data === undefined) {
    throw new PyTypeError("'NoneType' object is not iterable", frame(LINE_ITERATE));
  }

  for (const value of data) {
    if (value < 0n || shiftRight(value, frombits, LINE_CHECK_VALUE) !== 0n) return null;
    acc = (shiftLeft(acc, frombits, LINE_ACCUMULATE) | value) & maxAcc;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      ret.push((acc >> bits) & maxv);
    }
  }

  if (pad) {
    if (bits !== 0n) ret.push(shiftLeft(acc, tobits - bits, LINE_ACCUMULATE) & maxv);
  } else if (bits >= frombits || (shiftLeft(acc, tobits - bits, LINE_ACCUMULATE) & maxv) !== 0n) {
    return null;
  }
  return ret;
}

