    if (value < 0n || shiftRight(value, frombits, LINE_CHECK_VALUE) !== 0n) return null;
    acc = (shiftLeft(acc, frombits, LINE_ACCUMULATE) | value) & maxAcc;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
