function renderFrame(frame) {
  let text = `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;
  if (frame.source !== undefined) text += frame.source + '\n';
  if (frame.caret !== undefined) text += frame.caret + '\n';
