}

/**
 * Print a traceback for `error` and terminate with Python's exit status.
 *
 * @param {import('./pyerrors.mjs').PythonError} error
 * @param {Array<object>} callFrames Frames above the error's own frames.
 */
export function reportUnhandled(error, callFrames) {
  const frames = [...callFrames, ...(error.frames || [])];
  let out = 'Traceback (most recent call last):\n';
  for (const frame of frames) out += renderFrame(frame);
